from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class DetailedResult(SchemaObject):
    antl_id = SchemaField(name="antlId")
    phyant_id = SchemaField(name="phyantId")
    rmod_id = SchemaField(name="rmodId")
    product_name = SchemaField(name="productName")
    vswr = SchemaField(name="vswr")
    rssi_dbm = SchemaField(name="rssiDbm")
    sinr_db = SchemaField(name="sinrDb")
    fwd_etpw = SchemaField(name="fwdETPW", optional=True)
    fwd_et_pd_bm = SchemaField(name="fwdETPdBm", optional=True)
    rtwp = SchemaField(name="rtwp", optional=True)


    def __init__(self, antl_id, phyant_id, rmod_id, product_name, vswr, rssi_dbm, sinr_db, fwd_etpw, fwd_et_pd_bm,
                 rtwp):
        self.antl_id = antl_id
        self.phyant_id = phyant_id
        self.rmod_id = rmod_id
        self.product_name = product_name
        self.vswr = vswr
        self.rssi_dbm = rssi_dbm
        self.sinr_db = sinr_db
        self.fwd_etpw = fwd_etpw
        self.fwd_et_pd_bm = fwd_et_pd_bm
        self.rtwp = rtwp

        super(DetailedResult, self).__init__()


class GeneralTestInfo(SchemaObject):
    actual_start_time = SchemaField(name="actualStartTime")
    actual_stop_time = SchemaField(name="actualStopTime")
    result = SchemaField(name="result")
    test_outcome = SchemaField(name="testOutcome")
    test_outcome_additional_info = SchemaField(name="testOutcomeAdditionalInfo")
    fwd_test_disp = SchemaField(name="fwdTestDisp")
    rvrs_test_disp = SchemaField(name="rvrsTestDisp")
    fwd_etpw = SchemaField(name="fwdETPW")
    fwd_et_pd_bm = SchemaField(name="fwdETPdBm")
    rtwp = SchemaField(name="rtwp", optional=True)
    detailed_result = SchemaField(name="detailedResult", klass=DetailedResult, many=True)

    def __init__(self, actual_start_time, actual_stop_time, result, test_outcome, test_outcome_additional_info,
                 fwd_test_disp, rvrs_test_disp, fwd_etpw, fwd_et_pd_bm, rtwp, detailed_result):
        self.actual_start_time = actual_start_time
        self.actual_stop_time = actual_stop_time
        self.result = result
        self.test_outcome = test_outcome
        self.test_outcome_additional_info = test_outcome_additional_info
        self.fwd_test_disp = fwd_test_disp
        self.rvrs_test_disp = rvrs_test_disp
        self.fwd_etpw = fwd_etpw
        self.fwd_et_pd_bm = fwd_et_pd_bm
        self.rtwp = rtwp
        self.detailed_result = detailed_result

        super(GeneralTestInfo, self).__init__()


class RfDiagTestResultV1(SchemaObject):
    nr_cell_id = SchemaField(name="nrCellId", not_null=True)
    cell_name = SchemaField(name="cellName")
    dist_name = SchemaField(name="distName", not_null=True)
    general_test_info = SchemaField(name="generalTestInfo", klass=GeneralTestInfo)

    def __init__(self, nr_cell_id, cell_name, dist_name, general_test_info):

        self.nr_cell_id = nr_cell_id
        self.cell_name = cell_name
        self.dist_name = dist_name
        self.general_test_info = general_test_info

        super(RfDiagTestResultV1, self).__init__()


class RFDiagTestResult(SchemaObject):
    bts_id = SchemaField(name='btsId', not_null=True)
    bts_name = SchemaField(name='btsName', not_null=True)
    rf_diagnostic_test_results = SchemaField(name='rfDiagnosticTestResults', klass=RfDiagTestResultV1, many=True, not_null=True)

    def __init__(self, bts_id, bts_name, rf_diagnostic_test_results):
        self.bts_id = bts_id
        self.bts_name = bts_name
        self.rf_diagnostic_test_results = rf_diagnostic_test_results

        super(RFDiagTestResult, self).__init__()
